//! Wrapped native-token analogue for the Vegeta S3 WETH family.
use cosmwasm_std::{entry_point,to_json_binary,Addr,BankMsg,Binary,Coin,Deps,DepsMut,Env,MessageInfo,Response,StdError,StdResult,Uint128};use cw_storage_plus::{Item,Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{pub denom:String}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{Deposit{},Withdraw{amount:Uint128},Transfer{recipient:String,amount:Uint128},TransferFrom{owner:String,recipient:String,amount:Uint128},Approve{spender:String,amount:Uint128}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{Balance{address:String},Allowance{owner:String,spender:String},TotalSupply{}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct AmountResponse{pub amount:Uint128}
const DENOM:Item<String>=Item::new("denom");const TOTAL_SUPPLY:Item<Uint128>=Item::new("total_supply");const BALANCES:Map<&str,Uint128>=Map::new("balances");const ALLOWANCES:Map<(&str,&str),Uint128>=Map::new("allowances");
#[derive(Error,Debug,PartialEq)]pub enum ContractError{#[error("{0}")]Std(#[from]StdError),#[error("invalid funds")]InvalidFunds,#[error("insufficient funds")]InsufficientFunds,#[error("insufficient allowance")]InsufficientAllowance}
#[entry_point]pub fn instantiate(deps:DepsMut,_:Env,_:MessageInfo,msg:InstantiateMsg)->Result<Response,ContractError>{DENOM.save(deps.storage,&msg.denom)?;TOTAL_SUPPLY.save(deps.storage,&Uint128::zero())?;Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,_:Env,info:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::Deposit{}=>deposit(deps,info),ExecuteMsg::Withdraw{amount}=>withdraw(deps,info.sender,amount),ExecuteMsg::Transfer{recipient,amount}=>transfer(deps,info.sender,recipient,amount),ExecuteMsg::TransferFrom{owner,recipient,amount}=>transfer_from(deps,info.sender,owner,recipient,amount),ExecuteMsg::Approve{spender,amount}=>{let s=deps.api.addr_validate(&spender)?;ALLOWANCES.save(deps.storage,(info.sender.as_str(),s.as_str()),&amount)?;Ok(Response::new())}}}
fn deposit(deps:DepsMut,info:MessageInfo)->Result<Response,ContractError>{let denom=DENOM.load(deps.storage)?;let amount=info.funds.iter().find(|c|c.denom==denom).map(|c|c.amount).unwrap_or_default();if amount.is_zero()||info.funds.iter().any(|c|c.denom!=denom){return Err(ContractError::InvalidFunds)};credit(deps.storage,info.sender.as_str(),amount)?;TOTAL_SUPPLY.update(deps.storage,|x|x.checked_add(amount).map_err(StdError::overflow))?;Ok(Response::new())}
fn withdraw(deps:DepsMut,sender:Addr,amount:Uint128)->Result<Response,ContractError>{debit(deps.storage,sender.as_str(),amount)?;TOTAL_SUPPLY.update(deps.storage,|x|x.checked_sub(amount).map_err(StdError::overflow))?;let denom=DENOM.load(deps.storage)?;Ok(Response::new().add_message(BankMsg::Send{to_address:sender.into_string(),amount:vec![Coin{denom,amount}]}))}
fn transfer(deps:DepsMut,sender:Addr,recipient:String,amount:Uint128)->Result<Response,ContractError>{let r=deps.api.addr_validate(&recipient)?;debit(deps.storage,sender.as_str(),amount)?;credit(deps.storage,r.as_str(),amount)?;Ok(Response::new())}
fn transfer_from(deps:DepsMut,spender:Addr,owner:String,recipient:String,amount:Uint128)->Result<Response,ContractError>{let o=deps.api.addr_validate(&owner)?;let r=deps.api.addr_validate(&recipient)?;let a=ALLOWANCES.may_load(deps.storage,(o.as_str(),spender.as_str()))?.unwrap_or_default();if a<amount{return Err(ContractError::InsufficientAllowance)};ALLOWANCES.save(deps.storage,(o.as_str(),spender.as_str()),&a.checked_sub(amount).map_err(StdError::overflow)?)?;debit(deps.storage,o.as_str(),amount)?;credit(deps.storage,r.as_str(),amount)?;Ok(Response::new())}
fn debit(s:&mut dyn cosmwasm_std::Storage,a:&str,n:Uint128)->Result<(),ContractError>{let x=BALANCES.may_load(s,a)?.unwrap_or_default();if x<n{return Err(ContractError::InsufficientFunds)};BALANCES.save(s,a,&x.checked_sub(n).map_err(StdError::overflow)?)?;Ok(())}
fn credit(s:&mut dyn cosmwasm_std::Storage,a:&str,n:Uint128)->StdResult<()>{let x=BALANCES.may_load(s,a)?.unwrap_or_default();BALANCES.save(s,a,&x.checked_add(n).map_err(StdError::overflow)?) }
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::Balance{address}=>to_json_binary(&AmountResponse{amount:BALANCES.may_load(deps.storage,&address)?.unwrap_or_default()}),QueryMsg::Allowance{owner,spender}=>to_json_binary(&AmountResponse{amount:ALLOWANCES.may_load(deps.storage,(&owner,&spender))?.unwrap_or_default()}),QueryMsg::TotalSupply{}=>to_json_binary(&AmountResponse{amount:TOTAL_SUPPLY.load(deps.storage)?})}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn deposit_and_withdraw_track_supply(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("x",&[]),InstantiateMsg{denom:"ueth".into()}).unwrap();execute(d.as_mut(),mock_env(),mock_info("alice",&[Coin{denom:"ueth".into(),amount:Uint128::new(50)}]),ExecuteMsg::Deposit{}).unwrap();let r=execute(d.as_mut(),mock_env(),mock_info("alice",&[]),ExecuteMsg::Withdraw{amount:Uint128::new(20)}).unwrap();assert_eq!(r.messages.len(),1);assert_eq!(BALANCES.load(d.as_ref().storage,"alice").unwrap(),Uint128::new(30));}}
